namespace RonSijm.FluidHumidifier.Factories.DevOpsAgent;

public class InnerServiceServiceDetailsFactory(Action<Humidifier.DevOpsAgent.ServiceTypes.ServiceDetails> factoryAction = null) : SubResourceFactory<Humidifier.DevOpsAgent.ServiceTypes.ServiceDetails>
{

    internal InnerServiceMCPServerDetailsFactory MCPServerFactory { get; set; }

    internal InnerServiceServiceNowServiceDetailsFactory ServiceNowFactory { get; set; }

    internal InnerServiceGitHubDetailsFactory GitHubFactory { get; set; }

    internal InnerServiceAzureIdentityServiceDetailsFactory AzureIdentityFactory { get; set; }

    internal InnerServiceMCPServerGrafanaDetailsFactory MCPServerGrafanaFactory { get; set; }

    internal InnerServiceDynatraceServiceDetailsFactory DynatraceFactory { get; set; }

    internal InnerServiceMCPServerSigV4DetailsFactory MCPServerSigV4Factory { get; set; }

    internal InnerServiceMCPServerSplunkDetailsFactory MCPServerSplunkFactory { get; set; }

    internal InnerServiceNewRelicServiceDetailsFactory MCPServerNewRelicFactory { get; set; }

    internal InnerServiceGitLabDetailsFactory GitLabFactory { get; set; }

    internal InnerServicePagerDutyDetailsFactory PagerDutyFactory { get; set; }

    protected override Humidifier.DevOpsAgent.ServiceTypes.ServiceDetails Create()
    {
        var serviceDetailsResult = CreateServiceDetails();
        factoryAction?.Invoke(serviceDetailsResult);

        return serviceDetailsResult;
    }

    private Humidifier.DevOpsAgent.ServiceTypes.ServiceDetails CreateServiceDetails()
    {
        var serviceDetailsResult = new Humidifier.DevOpsAgent.ServiceTypes.ServiceDetails();

        return serviceDetailsResult;
    }
    public override void CreateChildren(Humidifier.DevOpsAgent.ServiceTypes.ServiceDetails result)
    {
        base.CreateChildren(result);

        result.MCPServer ??= MCPServerFactory?.Build();
        result.ServiceNow ??= ServiceNowFactory?.Build();
        result.GitHub ??= GitHubFactory?.Build();
        result.AzureIdentity ??= AzureIdentityFactory?.Build();
        result.MCPServerGrafana ??= MCPServerGrafanaFactory?.Build();
        result.Dynatrace ??= DynatraceFactory?.Build();
        result.MCPServerSigV4 ??= MCPServerSigV4Factory?.Build();
        result.MCPServerSplunk ??= MCPServerSplunkFactory?.Build();
        result.MCPServerNewRelic ??= MCPServerNewRelicFactory?.Build();
        result.GitLab ??= GitLabFactory?.Build();
        result.PagerDuty ??= PagerDutyFactory?.Build();
    }

} // End Of Class

